def sieve_of_eratosthenes(limit: int) -> list[int]:
    """Find all prime numbers up to a given limit.
    Time Complexity: O(n log log n).
    """
    if limit < 2:
        return []
    primes = [True] * (limit + 1)
    primes[0] = primes[1] = False
    for p in range(2, int(limit**0.5) + 1):
        if primes[p]:
