def binary_search(arr: list[int], target: int) -> int:
    """Find index of target in a sorted list using binary search.
    Returns -1 if target is not found.
    Time Complexity: O(log n), Space Complexity: O(1).
    """
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

